function api(path, data){ return fetch(path,{method:'POST',headers:apiHeaders(),body:JSON.stringify(data||{})}); }
function apiGet(path){ return fetch(path,{method:'GET',headers:{'X-MW-Token':MW_TOKEN}}); }
